css:
&.slide.tpl {
  padding: 92px 110px; display:flex; flex-direction:column; justify-content:center; gap:32px;
  header p { color:var(--accent); font:600 25px var(--font-mono); text-transform:uppercase; letter-spacing:.13em; margin:0 0 14px; }
  header h2 { font-size:78px; line-height:1.06; margin:0; }
  .passage { position:relative; height:530px; border-block:2px solid var(--line); background:radial-gradient(ellipse at center,color-mix(in srgb,var(--accent) 13%,transparent),transparent 58%); }
  .track { position:absolute; inset:0; width:100%; height:100%; fill:none; stroke:var(--accent); stroke-width:2; stroke-dasharray:5 8; opacity:.65; }
  .hub { position:absolute; left:50%; top:43%; width:280px; height:280px; margin:-140px; border-radius:50%; border:2px solid var(--accent); display:grid; place-items:center; z-index:2; box-shadow:0 0 70px color-mix(in srgb,var(--accent) 23%,transparent); background:var(--bg); }
  .hub::after { content:''; position:absolute; inset:-18px; border-radius:50%; border:3px dashed color-mix(in srgb,var(--accent) 46%,transparent); }
  .hub img { width:170px; height:170px; border-radius:28px; object-fit:cover; }
  .hub-label { position:absolute; top:78%; width:28%; left:36%; text-align:center; color:var(--muted); font-size:30px; }
  .image-step { position:absolute; inset:0; margin:0; opacity:1!important; visibility:hidden; pointer-events:none; }
  .image-step img { position:absolute; top:43%; left:16%; width:235px; height:235px; padding:12px; border-radius:22px; object-fit:contain; background:white; transform:translate(-50%,-50%); box-shadow:0 8px 38px #0004; }
  .image-step b,.image-step span { position:absolute; top:77%; width:31%; text-align:center; font-size:35px; line-height:1.2; }
  .image-step b { left:.5%; } .image-step span { right:.5%; color:var(--accent); font-weight:650; opacity:0; }
  .image-step:first-of-type,.image-step.in,.image-step:not([data-step]) { visibility:inherit; }
  .image-step:has(~.image-step.in),.image-step:not([data-step]):has(~.image-step) { visibility:hidden; }
  .image-step.in img,.image-step:not([data-step]) img { left:84%; transition:left 1.25s cubic-bezier(.56,.02,.26,1) .8s; }
  .image-step.in span,.image-step:not([data-step]) span { opacity:1; transition:opacity .4s 1.88s; }
  .image-step img { offset-path:path("M272 228 C465 228 545 65 850 228 S1250 228 1428 228"); offset-rotate:0deg; offset-distance:0%; transform:none; left:0; top:0; }
  .image-step.in img,.image-step:not([data-step]) img { left:0; offset-distance:100%; transition:offset-distance 1.5s cubic-bezier(.56,.02,.26,1) .85s; }
  .image-step:has(span:empty).in img,.image-step:not([data-step]):has(span:empty) img { offset-distance:50%; scale:.18; transition:offset-distance 1.35s ease-in-out .9s,scale .55s ease 1.7s; }
  .hub::after { transition:transform .95s ease 1.2s,box-shadow .95s ease 1.2s; }
  .passage:has(.step-current:nth-of-type(odd)) .hub::after { transform:rotate(32deg) scale(1.09); box-shadow:0 0 35px color-mix(in srgb,var(--accent) 30%,transparent); }
  .lead { margin:0; color:var(--muted); font-size:33px; max-width:80ch; }
  &[data-body-motion="none"] *,& .image-step:not([data-step]) * { transition:none!important; }
  @media(prefers-reduced-motion:reduce) { & * {transition:none!important;} }
}
